entries[151761] = { ["name"] = "Hingekritzelte Hetzereien", ["text"] = "Wird beim Aufheben gebunden\n\"Die Handschrift auf der Rolle ist gezackt und wirkt hektisch, kommt Euch aber irgendwie bekannt vor.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[151762] = { ["name"] = "Aschenwinduniform", ["text"] = "Questgegenstand\nBenutzen: Kombiniert 5 Stücke Aschenwindkleidung, um eine Verkleidung herzustellen.\n\nFunktioniert nur in den von Aschenwind besetzten Bereichen von Vol'dun. (15 Sek. Abklingzeit)" }
