entries[151774] = { ["name"] = "Destillierte Leerenmischung", ["text"] = "Benutzen: Ein starkes alkoholisches Getränk.\n\"Immer kalt.\"\nVerkaufspreis:" }
entries[151775] = { ["name"] = "Nährkondensat", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 10000 * 20 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Enthält Nährstoffe. Das war's aber auch schon.\"\nVerkaufspreis:" }
entries[151776] = { ["name"] = "Kiste mit Schweinefleischprodukten", ["text"] = "Questgegenstand\n\"Fragwürdige verarbeitete Schweinefleischprodukte.\"" }
entries[151777] = { ["name"] = "Schlüssel der Aschenwindhändler", ["text"] = "Questgegenstand" }
entries[151778] = { ["name"] = "Shoaks Artefakt", ["text"] = "Questgegenstand\n\"Ihr bemerkt, dass sich auf diesem Artefakt Symbole befinden, die Bwonsamdi zugeschrieben werden.\"" }
entries[151782] = { ["name"] = "Der Turm ohne Spitze", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nKopf Platte\n13 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 120 / 120\nKlassen: Paladin\nAnlegen: 'Licht der Morgendämmerung' hat eine Chance von 10%, Euch 8 Sek. lang 'Zornige Vergeltung' zu gewähren.\n\"Es ist immer ein Kommen und Gehen,wenn es um Alleria und Turalyon geht.\"\nVerkaufspreis:" }
entries[151783] = { ["name"] = "Karma des Chamäleons", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nKopf Leder\n6 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure Tempowertung um + 5.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 120 / 120\nKlassen: Druide\nAnlegen: 'Wildwuchs' hat eine Chance von 15%, Euch für 12 Sek. 'Inkarnation: Baum des Lebens' zu gewähren.\n\"Die Hüter bewahren den Frieden mit dem Wissen, dass nichts ewig währt – nicht der Baum, nicht die Liebe, nicht einmal ein gewaltsamer Tod.\"\nVerkaufspreis:" }
entries[151784] = { ["name"] = "Pforte ins Nirgendwo", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 3.\nKlassen: Mönch\nAnlegen: 'Essenzborn' hat eine Chance von 20%, für bis Abbruch Chi-Ji zu beschwören.\n\"Zwei Wege boten sich im Nebel dar. / Ich nahm den dritten, der weniger begangen war.\"\nVerkaufspreis:" }
entries[151785] = { ["name"] = "Flammen der Tiefe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBrust Kette\n12 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 200 / 200\nKlassen: Schamane\nAnlegen: 'Heilender Regen' hat eine Chance von 15%, für 6 Sek. 'Aszendenz' auszulösen.\n\"Und der Dämonen Zorn sei ihrer Geltung Schmach; / und in des Erden Schrein lagen die Götzen brach.\"\nVerkaufspreis:" }
entries[151786] = { ["name"] = "Innerer Lichtschein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nSchulter Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 120 / 120\nKlassen: Priester\nAnlegen: 'Machtwort: Glanz' hat eine Chance von 35%, Euch 9 Sek. lang 'Seele der Macht' zu gewähren.\n\"Leiht mir Eure Macht, und die Unsterblichkeit wird unser sein.\"\nVerkaufspreis:" }
entries[151787] = { ["name"] = "Die Alabasterlady", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nKopf Stoff\n4 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 120 / 120\nKlassen: Priester\nAnlegen: 'Gebet der Besserung' hat eine Chance von 15%, für 8 Sek. 'Apotheose' auszulösen.\n\"Als der Sterne Speere schossen / und Tränen in den Himmel gossen, / sah lächelnd sie ihr Werk vor sich?\"\nVerkaufspreis:" }
entries[151788] = { ["name"] = "Sturmbräus letzter Atemzug", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nSchulter Leder\n6 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 3.\n+ 4 Vielseitigkeit\nHaltbarkeit 120 / 120\nKlassen: Mönch\nAnlegen: 'Fasshieb' erhält 1 zusätzliche Aufladung und verursacht 25% mehr Schaden.\n\"Warum kämpfen wir? Um Heimat und Familie zu beschützen... Um Gleichgewicht zu wahren und Harmonie zu schaffen.\"\nVerkaufspreis:" }
entries[151789] = { ["name"] = "Verteidigungskonstruktidentifikator", ["text"] = "Wird beim Aufheben gebunden\n\"Markiert den Träger als vom Vernichtungsprotokoll ausgeschlossen.\"\nVerkaufspreis:" }
entries[151790] = { ["name"] = "Rote Winterkleidung", ["text"] = "Kosmetisch\nWird beim Anlegen gebunden\nBrust Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\n\nWintergewandung (0/3)\nGrüne Winterkleidung\nGrüne Wintermütze\nRote Winterkleidung\nRote Wintermütze\nWinterstiefel\n(3) Set : Gesamte Wintergewandung\nVerkaufspreis:" }
entries[151791] = { ["name"] = "Winterstiefel", ["text"] = "Kosmetisch\nWird beim Anlegen gebunden\nFüße Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\n\nWintergewandung (0/3)\nGrüne Winterkleidung\nGrüne Wintermütze\nRote Winterkleidung\nRote Wintermütze\nWinterstiefel\n(3) Set : Gesamte Wintergewandung\nVerkaufspreis:" }
entries[151792] = { ["name"] = "Grüne Winterkleidung", ["text"] = "Kosmetisch\nWird beim Anlegen gebunden\nBrust Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\n\nWintergewandung (0/3)\nGrüne Winterkleidung\nGrüne Wintermütze\nRote Winterkleidung\nRote Wintermütze\nWinterstiefel\n(3) Set : Gesamte Wintergewandung\nVerkaufspreis:" }
entries[151793] = { ["name"] = "Schweinsfetisch", ["text"] = "Questgegenstand\nEinzigartig\n\"Verströmt eine schmierige, dunkle Magie und riecht wie angebrannter Speck.\"" }
entries[151795] = { ["name"] = "Verderbnis des Seelenschinders", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBrust Platte\n18 Rüstung\n+5 Stärke\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 200 / 200\nKlassen: Todesritter\nAnlegen: Erhöht den Schaden und die Heilung von 'Blutseuche' um 100%.\n\"Die Herkunft des Seelenschinders bleibt ein Rätsel. In den Annalen der Titanen findet sich keinerlei Eintrag über ihn.\"\nVerkaufspreis:" }
entries[151796] = { ["name"] = "Kaltes Herz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBrust Platte\n18 Rüstung\n+5 Stärke\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 200 / 200\nKlassen: Todesritter\nAnlegen: Gewährt Euch alle 2 Sek. einen Stapel von 'Kaltes Herz', wodurch Euer nächster Einsatz von 'Eisketten' (21% der Angriffskraft) Schattenfrostschaden verursacht. Bis zu 20-mal stapelbar.\n\nWenn Ihr beim Einsatz von 'Eisketten' 20 Stapel von 'Kaltes Herz' habt, wird das Ziel außerdem für 4 Sek. betäubt und in einen Eisblock eingeschlossen.\n\"Das Schlagen eines gefrorenen Herzens ist auch in weiter Ferne noch hörbar und erinnert alles Lebende an die Unausweichlichkeit des Todes.\"\nVerkaufspreis:" }
entries[151798] = { ["name"] = "Chaostheorie", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 Beweglichkeit\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 3.\nKlassen: Dämonenjäger\nAnlegen: 'Klingentanz' hat eine Chance von 10%, Euch 6 Sek. lang 'Chaosklingen' zu gewähren. (500ms Abklingzeit)\n\"Das Chaos birgt Wiederholung, Rückkopplungsschleifen und zugrundeliegende Muster.\"\nVerkaufspreis:" }
entries[151799] = { ["name"] = "Umarmung des Vergessens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBeine Leder\n7 Rüstung\n+5 Beweglichkeit\n+7 Ausdauer\n+ 5 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 145 / 145\nKlassen: Dämonenjäger\nAnlegen: 'Dämonenstachel' erhält 1 zusätzliche Aufladung.\n\"Es gibt keinen besseren Ratgeber für die Welt als Vergessen.\"\nVerkaufspreis:" }
entries[151800] = { ["name"] = "Strahlendes Mondlicht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 3.\nKlassen: Druide\nAnlegen: 'Vollmond' wird nach dem Einsatz noch einmal zu 'Vollmond', bevor der Zyklus auf 'Neumond' zurückgesetzt wird.\n\"Zweifelt an der Sonne Klarheit,Zweifelt an der Sterne Licht.\"\nVerkaufspreis:" }
entries[151801] = { ["name"] = "Kopfputz des Ungetüms", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nKopf Leder\n6 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 120 / 120\nKlassen: Druide\nAnlegen: Finishing-Moves verlängern die Dauer von 'Tigerfuror' pro verbrauchtem Combopunkt um 0.5 Sek. (100ms Abklingzeit)\n\"Schlafende Tiger soll man nicht wecken.\"\nVerkaufspreis:" }
entries[151802] = { ["name"] = "Furor der Natur", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 3.\nKlassen: Druide\nAnlegen: In Bärengestalt verursacht Ihr 30% mehr Natur- und Arkanschaden und werdet um 30% Eures verursachten Natur- und Arkanschadens geheilt.\n\"Ein Gleichgewicht zwischen den natürlichen und übernatürlichen Kräften mag schwer zu erreichen sein, doch es führt zu wahrer Größe.\"\nVerkaufspreis:" }
entries[151803] = { ["name"] = "Schnelligkeit der Windläufer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 Beweglichkeit\n+4 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 3.\nKlassen: Jäger\nAnlegen: Erhöht Euer Tempo um 3%.\nAnlegen: 'Windstoß' erhöht 6 Sek. lang Euer Tempo um 15%.\n\"'Dein Herz flog geradlinig wie ein Pfeil mit dem Wind, Schwester. Du warst die Strahlendste unseres Ordens. Du warst die Teuerste unserer Sippe.' - Sylvanas an Alleria\"\nVerkaufspreis:" }
entries[151804] = { ["name"] = "Schwarze Smokinghose", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nBeine Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\n\nFrühlingsfrack (0/2)\nSchwarze Smokinghose\nWeißes Smokinghemd\n(2) Set : Frühlingsfrack\nVerkaufspreis:" }
entries[151805] = { ["name"] = "Die Parselzunge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBrust Kette\n12 Rüstung\n+5 Beweglichkeit\n+7 Ausdauer\nErhöht Eure Tempowertung um + 5.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 200 / 200\nKlassen: Jäger\nAnlegen: 'Kobraschuss' erhöht 8 Sek. lang Euren verursachten Schaden und den Eurer Begleiter um 1% sowie Euren Lebensraub um 2%. Dieser Effekt ist bis zu 4-mal stapelbar. (500ms Abklingzeit)\n\"Eine seltene Fähigkeit, die jene besitzen, die Umgang mit Schlangen haben.\"\nVerkaufspreis:" }
entries[151806] = { ["name"] = "Elegantes Kleid", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nBrust Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[151807] = { ["name"] = "Umhang des unsichtbaren Raubtiers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 Beweglichkeit\n+4 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 3.\nKlassen: Jäger\nAnlegen: Erhöht sämtlichen verursachten Schaden um 3%.\nAnlegen: Erhöht Eure kritische Trefferchance gegen Ziele, die von dem Effekt Eurer 'Sprengfalle' betroffen sind, um 10%.\n\"Selbst der mächtigste Gegner hat eine Schwäche. Sie muss nur aufgedeckt werden.\"\nVerkaufspreis:" }
entries[151808] = { ["name"] = "Mantel der Ersten der Kirin Tor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nSchulter Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 120 / 120\nKlassen: Magier\nAnlegen: 'Arkanbeschuss' hat pro verbrauchter Arkaner Aufladung eine Chance von 10%, eine 'Arkane Kugel' vor Euch abzufeuern.\n\"Vor tausenden Jahren unterwiesen die Hochelven von Quel'Thalas die Menschen in den arkanen Künsten, woraufhin diese die Kirin Tor gründeten und schließlich über Dalaran herrschten.\"\nVerkaufspreis:" }
entries[151809] = { ["name"] = "Gebändigter Höllenbestienkern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nSchulter Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 120 / 120\nKlassen: Magier\nAnlegen: Nachdem Ihr 30-mal 'Feuerball' oder 'Pyroschlag' gewirkt habt, wird ein 'Meteor' auf Euer Ziel gestürzt.\n\"Der Höllenbestienkern entlädt sich häufig in explosiven Flammenstrahlen so heiß, dass sie selbst widerstandsfähigste Materialien schmelzen.\"\nVerkaufspreis:" }
entries[151810] = { ["name"] = "Zerschmetterte Fragmente von Sindragosa", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nKopf Stoff\n4 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Tempowertung um + 5.\nHaltbarkeit 120 / 120\nKlassen: Magier\nAnlegen: Nachdem Ihr 15-mal 'Frostblitz' oder 'Hagel' gewirkt habt, geht ein 'Kometenhagel' auf Euer Ziel nieder.\n\"Wurde aus den Trümmern gefertigt, die Arthas nach seiner Verwüstung bei Sindragosas Sturz hinterließ, und jagt seinem Träger einen Schauer über den Rücken.\"\nVerkaufspreis:" }
entries[151811] = { ["name"] = "Der Wind weht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nKopf Leder\n6 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 120 / 120\nKlassen: Mönch\nAnlegen: Erhöht Euren verursachten Schaden um 3%.\nAnlegen: Verringert die Abklingzeit von 'Schlag des Windlords' um 20% und hebt die Chikosten Eures nächsten Einsatzes von 'Blackout-Tritt' auf. (1s Abklingzeit)\n\"Die Sonne geht auf, der Wind weht und die Mächtigen fallen.\"\nVerkaufspreis:" }
entries[151812] = { ["name"] = "Säulen des innersten Lichts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nSchulter Platte\n12 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 120 / 120\nKlassen: Paladin\nAnlegen: Verringert die Abklingzeit von 'Unermüdlicher Verteidiger' um 25%.\nAnlegen: 'Auge von Tyr' verursacht 300% mehr Schaden und die Abklingzeit ist um 25% verringert.\n\"Das Licht brennt am hellsten in jenen, die es verschlingt.\"\nVerkaufspreis:" }
entries[151813] = { ["name"] = "Bann des scharlachroten Inquisitors", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBrust Platte\n18 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure Tempowertung um + 5.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 200 / 200\nKlassen: Paladin\nAnlegen: Erhöht alle 2 Sek. den Schaden Eures nächsten Einsatzes von 'Göttlicher Sturm' um 6%. Bis zu 30-mal stapelbar.\n\"Versteht Ihr es nicht, Brüder und Schwestern? Es gibt nur einen Weg, die Geißel vom Antlitz Azeroths zu fegen.\"\nVerkaufspreis:" }
entries[151814] = { ["name"] = "Herz der Leere", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBrust Stoff\n5 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Tempowertung um + 5.\nHaltbarkeit 200 / 200\nKlassen: Priester\nAnlegen: 'Leereneruption' verursacht 75% mehr Schaden und heilt Euch um 25% des verursachten Schadens.\n\"Die Leere ist keinesfalls leer. Sie ist voll von Bosheit, Verzweiflung und Tod.\"\nVerkaufspreis:" }
entries[151815] = { ["name"] = "Die leere Krone", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nKopf Leder\n6 Rüstung\n+5 Beweglichkeit\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 120 / 120\nKlassen: Schurke\nAnlegen: Energieregeneration um 1 pro Sekunde erhöht. (500ms Abklingzeit)\nAnlegen: 'Königsmord' erzeugt im Verlauf von 5 Sek. 40 Energie. (500ms Abklingzeit)\n\"Es ist schwer, einen Hund an die Leine zu legen, wenn man ihm einmal eine Krone auf seinen Kopf gesetzt hat.\"\nVerkaufspreis:" }
entries[151816] = { ["name"] = "Hordebanner", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Platziert ein Hordenbanner auf dem Leichnam eines Zanchuliverräters in der Nähe." }
entries[151817] = { ["name"] = "Der Fluch der Ruhelosigkeit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 Beweglichkeit\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 3.\nKlassen: Schurke\nAnlegen: 'Ruhlose Klingen' verringert pro verbrauchtem Combopunkt die Abklingzeit von 'Adrenalinrausch' um 0.5 Sek.\nAnlegen: 'Ruhlose Klingen' verringert pro verbrauchtem Combopunkt die Abklingzeit von 'Fluch der Schreckensklingen' um 0.25 Sek.\n\"Wer rastet, der rostet... und wird gemeuchelt!\"\nVerkaufspreis:" }
entries[151818] = { ["name"] = "Der erste Tote", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHände Leder\n5 Rüstung\n+4 Beweglichkeit\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 70 / 70\nKlassen: Schurke\nAnlegen: Für 2 Sek. nach der Aktivierung von 'Symbole des Todes' erzeugt 'Schattenschlag' 3 zusätzliche Combopunkte und 'Meucheln' 4 zusätzliche Combopunkte. (500ms Abklingzeit)\n\"Am Ende findet der Tod uns alle...\"\nVerkaufspreis:" }
entries[151819] = { ["name"] = "Schwelendes Herz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHände Kette\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Schamane\nAnlegen: Gewährt Euch pro verbrauchtem Punkt Mahlstrom eine Chance von [ Sturmschlag : 0.12% / 0.10%], für 10 Sek. 'Aszendenz' auszulösen.\n\"Diese Handschuhe wurden erfüllt mit der Essenz von tausenden lodernden Elementaren – und doch fühlen sie sich seltsam kalt an.\"\nVerkaufspreis:" }
entries[151821] = { ["name"] = "Der Meister der Ernte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBrust Stoff\n5 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nErhöht Eure Tempowertung um + 5.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 200 / 200\nKlassen: Hexenmeister\nAnlegen: Dämonologie\nJeder Seelensplitter, den Ihr verbraucht, hat eine Chance von 3%, Euch 8 Sek. lang 'Seelenernte' zu gewähren.\n\nZerstörung\nJeder Seelensplitter, den Ihr verbraucht, hat eine Chance von 6%, Euch 8 Sek. lang 'Seelenernte' zu gewähren.\n\nGebrechen\nJeder Seelensplitter, den Ihr verbraucht, hat eine Chance von 9%, Euch 8 Sek. lang 'Seelenernte' zu gewähren.\n\"Aus Leid geht die stärkste aller Seelen hervor.\"\nVerkaufspreis:" }
entries[151822] = { ["name"] = "Ararats Blutspiegel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBeine Platte\n16 Rüstung\n+5 Stärke\n+7 Ausdauer\n+ 5 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 145 / 145\nKlassen: Krieger\nAnlegen: Gewährt 'Schildblock' und 'Zauberreflexion' 1 zusätzliche Aufladung.\n\"Sein Blut tränkt den glänzenden Stahl, vergossen von Drachen, Göttern und Dämonen. Selbst von der anderen Seite beschützt er seine Freunde.\"\nVerkaufspreis:" }
entries[151823] = { ["name"] = "Das Auge des großen Sturms", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nKopf Platte\n13 Rüstung\n+5 Stärke\n+7 Ausdauer\nErhöht Eure Tempowertung um + 5.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 120 / 120\nKlassen: Krieger\nAnlegen: 'Klingensturm' erhöht 6 Sek. lang Eure Bewegungsgeschwindigkeit um 10% und Euren verursachten Schaden um 2%. Dieser Effekt wird in regelmäßigen Abständen stärker und ist bis zu 6-mal stapelbar.\n\"Im Auge des Tornados gibt es kein hoch oder tief, keinen Boden, keinen Himmel.\"\nVerkaufspreis:" }
entries[151824] = { ["name"] = "Berserker der Valarjar", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nBeine Platte\n16 Rüstung\n+5 Stärke\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 6.\nHaltbarkeit 145 / 145\nKlassen: Krieger\nAnlegen: Kritische Treffer mit 'Toben' gegen das Primärziel erzeugen 6 Wut.\n\"Fingerspitzengefühl ist nicht unbedingt ihr hervorstechendstes Merkmal.\"\nVerkaufspreis:" }
entries[151825] = { ["name"] = "Hatuuns Horn", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Beschwört Krokulgratpirscher aus den Schatten, die Euch im Kampf unterstützen. (30 Sek. Abklingzeit)\n\"Lasst den Ruf der Schlacht erklingen. Wir schlagen vereint zu!\"" }
entries[151826] = { ["name"] = "Geistermaske", ["text"] = "Questgegenstand\nBenutzen: Benutzt die Geistermaske, um in das Geisterreich überzugehen." }
entries[151828] = { ["name"] = "Nie alternder Bronzedrache", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick Euren Protowelpen beschwören oder wieder freigeben.\n80 ( 80)\nMit der Veröffentlichung von \"Legion Remix: Legionsrichter\" verfügbar.\nVerkaufspreis:" }
entries[151829] = { ["name"] = "Bronzener Protowelpe", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick Euren Protowelpen beschwören oder wieder freigeben.\n80 ( 80)\nMit der Veröffentlichung von \"Legion Remix: Legionsrichter\" verfügbar.\nVerkaufspreis:" }
entries[151830] = { ["name"] = "Urteil des Lichts", ["text"] = "Benutzen: Ruft die Vindikaar, damit sie einen Strahl heiligen Lichts auf Eure Gegner abfeuert, der Gegnern innerhalb von 15 Metern 100 Heiligschaden zufügt und sie für 5 Sek. betäubt.\n\nKann nur auf Argus eingesetzt werden. (2 Min Abklingzeit)" }
entries[151837] = { ["name"] = "Anrufungsrelais", ["text"] = "Questgegenstand\n\"Diese langen und dünnen Kristalle fokussieren Licht zu mächtigen Explosionen und sind daher recht begehrt.\"" }
entries[151838] = { ["name"] = "Urteilskern", ["text"] = "Questgegenstand\n\"Man sagt, dass der Urteilskern den krönenden Erfolg der Konstrukteure der Armee des Lichts darstellt.\"" }
entries[151839] = { ["name"] = "Verteidigerpanzerung", ["text"] = "Questgegenstand\n\"Die lichtgeschmiedete Rüstung der Großen Armee ist darauf ausgelegt, ihre Verteidiger vor der Teufelsmagie der Legion zu schützen.\"" }
entries[151842] = { ["name"] = "Krokulrüstungsset", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Setzt die Machtstufe eines Champions auf 900.\nVerkaufspreis:" }
entries[151843] = { ["name"] = "Rüstungsset von Eredath", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Setzt die Machtstufe eines Champions auf 925.\nVerkaufspreis:" }
entries[151844] = { ["name"] = "Rüstungsset der Xenedar", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Setzt die Machtstufe eines Champions auf 950.\nVerkaufspreis:" }
entries[151845] = { ["name"] = "Gebrauchte Phiole", ["text"] = "Questgegenstand\n\"Es scheinen sich Spuren einer Art goldener Flüssigkeit darin zu befinden.\"" }
entries[151848] = { ["name"] = "Eisenerz", ["text"] = "Hauptkriegsfrontenprototyp" }
entries[151849] = { ["name"] = "Schriftrolle des Infernos", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Liest eine magische Schriftrolle, um profane Totems in der Nähe zu zerstören. (5 Sek. Abklingzeit)" }
entries[151851] = { ["name"] = "Makelloser Teufelskern", ["text"] = "Questgegenstand\n\"Das mit chaotischer Energie erfüllte Herz eines reinen Teufelswesens.\"" }
entries[151852] = { ["name"] = "Edikte des Gral", ["text"] = "Questgegenstand\n\"Der Text dieser Schriftrolle ist in einem uralten Trolldialekt verfasst und mithilfe eines besonderen Codes verschlüsselt. Man könnte ein Leben damit verbringen, ihn zu entschlüsseln.\"" }
entries[151853] = { ["name"] = "Wellen der Macht", ["text"] = "Questgegenstand\n\"Mithilfe uralter Zauberei wurde diese Schriftrolle mit Symbolen verziert, die für Euch unbegreiflich sind.\"" }
entries[151854] = { ["name"] = "Schriftrolle des Läuterns", ["text"] = "Questgegenstand\n\"Auf dieser uralten Schriftrolle ist nur der Titel des Zaubers lesbar.\"" }
entries[151855] = { ["name"] = "Artefakt von Gral", ["text"] = "Questgegenstand\n\"Für Laien sieht dieses Relikt nur wie ein hübsches Stück einer Ruine aus.\"" }
entries[151856] = { ["name"] = "Verwelkte Astralwinde", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Eine nicht verwendbare Form des Krauts.\"" }
entries[151857] = { ["name"] = "Junge Astralwinde", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Ein Astralwindenschössling.\"" }
entries[151858] = { ["name"] = "Astralwindenwurzelballen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Ein kleiner, an einen Kokon erinnernder Wurzelballen, aus dessen Inneren Energie zu dringen scheint.\"" }
entries[151859] = { ["name"] = "Schriftrolle der Illusion", ["text"] = "Questgegenstand\nBenutzen: Maskiert eine Antiquität von Gral.\n\"Die Zauber auf dieser Seite sind sehr speziell und wurden so vereinfacht, dass selbst die schlichtesten Gemüter sie anwenden können.\"" }
entries[151860] = { ["name"] = "Brocken eines Empyriumvorkommens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Die Oberfläche dieses Erzes glitzert wie die Sterne.\"" }
entries[151861] = { ["name"] = "Empyriumstaub", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Kleine Überreste von Empyriumerz.\"" }
entries[151862] = { ["name"] = "Unbrauchbarer Empyriumkern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Ein zerbrochener Empyriumerzkern.\"" }
entries[151863] = { ["name"] = "Brocken eines Empyriumflözes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Die Oberfläche dieses Erzes glitzert wie die Sterne.\"" }
entries[151864] = { ["name"] = "Eingebettetes Empyriumerz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Ein Brocken Empyriumerz mit großen Teilen nicht verwendbaren Gesteins.\"" }
entries[151865] = { ["name"] = "Empyriumfragmente", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Kleine Stücke Empyriumerz.\"" }
entries[151866] = { ["name"] = "Besudelte Fetzen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Diese Fetzen von infernalischem Leder scheinen verderbt zu sein und verbreiten einen sehr üblen Gestank.\"" }
entries[151867] = { ["name"] = "Verdorbenes infernalisches Leder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Die von dem Tier ausgehende Verderbnis hat dieses Stück Leder verdorben.\"" }
entries[151868] = { ["name"] = "Verderbter Zahn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Die Verderbnis dieses Tiers hat seinen Zahn erreicht und ihn nutzlos gemacht.\"" }
entries[151870] = { ["name"] = "Schriftrolle des Gral", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Nimmt die Gestalt eines Hais an." }
entries[151871] = { ["name"] = "Kiste mit Teufelsschiefer", ["text"] = "Questgegenstand\n\"Eine große Kiste mit Teufelsschiefererz.\"" }
entries[151872] = { ["name"] = "Empyriumbrustplatte", ["text"] = "Questgegenstand\n\"Ein schimmerndes Stück einer weiß-goldenen Rüstung.\"" }
entries[151874] = { ["name"] = "Leuchtgarnwebstuhl", ["text"] = "Questgegenstand\n\"Ein dekorativer Webstuhl mit goldener Gravur.\"" }
entries[151875] = { ["name"] = "Ruf zum Licht", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Ruft einen Champion des Lichts herbei, der 12 Sek. lang für Euch kämpft." }
entries[151876] = { ["name"] = "Vorels Vorlagenbuch", ["text"] = "Questgegenstand\n\"Ein großer Foliant mit verschiedenen Juwelenschliffdesigns.\"" }
entries[151877] = { ["name"] = "Fass mit Augenklappen", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nKlassen: Schurke\nBenutzen: Beschwört ein Fass voller geheimnisvoller Augenklappen für Euch und all Eure Freunde. Das Resultat wird kaum zu FASSen sein! (1 Stunde Abklingzeit)\n\"So viel Spaß auf einmal! Ihr werdet gaaarrr nicht wissen, was Ihr zuerst damit anstellen sollt.\"" }
entries[151878] = { ["name"] = "Empyriumkrone", ["text"] = "Questgegenstand\n\"Jeder Edelstein in dieser Krone ist so platziert, dass er wie ein Stern glitzert.\"" }
entries[151879] = { ["name"] = "Geläutertes infernalisches Leder", ["text"] = "Questgegenstand\n\"Die geläuterte Variante dieses Leders stinkt nicht mehr und Ihr fühlt Euch auch nicht mehr unwohl, wenn Ihr es haltet.\"" }
entries[151880] = { ["name"] = "Enstraas Gerböl", ["text"] = "Questgegenstand\nBenutzen: Kombiniert 1 infernalisches Leder und 1 lichtgewirktes Tuch mit Enstraas Gerböl.\n\"Eine kleine Phiole mit einer klaren, goldenen Flüssigkeit. Wenn Ihr sie öffnet, entweicht ein blumiger Duft.\"" }
