entries[151955] = { ["name"] = "Ätzende Katalysatoreinspritzdüse", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Intelligenz\nAnlegen: Kritische Treffer mit Euren Schadenszaubern haben eine Chance, Euer Tempo, Eure Meisterschaft oder Euren kritischen Trefferwert für 45 Sek. um 1 zu erhöhen. Bis zu 5-mal stapelbar. Wenn einer der Effekte 5 Stapel erreicht, werden alle Effekte verbraucht, um Euch für 12 Sek. eine Erhöhung aller drei Werte um 12 zu gewähren.\nVerkaufspreis:" }
entries[151956] = { ["name"] = "Rückkopplungsleitung der Garothi", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Intelligenz\nAnlegen: Eure Heilungseffekte haben eine Chance, Euer Tempo 8 Sek. lang um 5 zu erhöhen. Dieser Effekt ist bis zu 5-mal stapelbar. Dieser Effekt tritt häufiger auf, wenn Ihr Verbündete mit niedriger Gesundheit heilt.\nVerkaufspreis:" }
entries[151957] = { ["name"] = "Ishkars Teufelsschildemitter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 7 Vielseitigkeit\nBenutzen: Belegt einen Verbündeten mit einem 'Teufelsschild' der 9 Sek. lang [ 227 * (1 + Vielseitigkeit)] Schaden absorbiert. Wenn der Schild aufgebraucht wird oder abläuft, explodiert er und verursacht innerhalb von 8 Metern Feuerschaden in Höhe von 50 % des absorbierten Schadens, der gleichmäßig unter allen Gegnern aufgeteilt wird. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[151958] = { ["name"] = "Schlüsselstein von Tarratus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Intelligenz\nBenutzen: Öffnet ein Portal an der Position eines Verbündeten, das gleißendes Licht verströmt, das verletzte Verbündete innerhalb von 20 Metern um 227 Gesundheit heilt, die unter allen Zielen aufgeteilt wird. (1 Min, 30 Sek. Abklingzeit)\n\"Die Sonne Tarratus', einer Kerkerwelt für rebellische Dämonen, erstrahlt atemberaubend hell.\"\nVerkaufspreis:" }
entries[151960] = { ["name"] = "Karaffe des sengenden Lichts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Intelligenz\nBenutzen: Versengt einen Gegner mit heiligem Licht, das im Verlauf von 18 Sek. 98 Heiligschaden verursacht. Stellt jedes Mal 8 Mana wieder her, wenn Schaden verursacht wird. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[151961] = { ["name"] = "Legionsstählernes Schwungrad", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 7.\nVerkaufspreis:" }
entries[151962] = { ["name"] = "Prototyp eines Personaldezimierers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 7.\nAnlegen: Eure Distanzangriffe und Zauber haben eine Chance, eine Zielsuchrakete auszulösen, wenn Euer Ziel mindestens 10 Meter entfernt ist. Sie fügt allen Gegnern innerhalb von 20 Metern 28 Feuerschaden zu. Ziele, die sich näher am Einschlagsort befinden, erleiden mehr Schaden.\nVerkaufspreis:" }
entries[151963] = { ["name"] = "Fabrikator des Schmiedeschreckens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 7.\nAnlegen: Eure Nahkampf- und Distanzangriffe haben eine Chance, Feuerminen zu Füßen des Gegners abzulegen. Feuerminen detonieren nach 15 Sek. und fügen allen Gegnern innerhalb von 12 Metern 15 Feuerschaden zu.\nBenutzen: Detoniert alle Feuerminen. (30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[151964] = { ["name"] = "Triefende Geißelschwinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 7 Vielseitigkeit\nAnlegen: Eure Nahkampfangriffe haben eine Chance, dem Ziel 39 Schattenschaden zuzufügen. Wenn sich keine weiteren Gegner innerhalb von 8 Metern um das Ziel befinden, erleidet es zusätzlich 17 Schattenschaden.\nVerkaufspreis:" }
entries[151965] = { ["name"] = "Vulkanarkernanhänger", ["text"] = "Wird beim Aufheben gebunden\nHals\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 6.\n+ 8 Vielseitigkeit\nVerkaufspreis:" }
entries[151966] = { ["name"] = "Nietenhalsreif des Deliriums", ["text"] = "Wird beim Aufheben gebunden\nHals\n+4 Ausdauer\nErhöht Eure Tempowertung um + 8.\nErhöht Eure Meisterschaftswertung um + 6.\nVerkaufspreis:" }
entries[151968] = { ["name"] = "Schattenversengter Reißzahn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nAnlegen: Eure Nahkampf- und Distanzfähigkeiten haben eine Chance, Eure Stärke oder Beweglichkeit 12 Sek. lang um 9 zu erhöhen.\nAnlegen: Eure automatischen Angriffe haben eine Chance, Euren kritischen Trefferwert für 12 Sek. um 14 zu erhöhen.\nVerkaufspreis:" }
entries[151969] = { ["name"] = "Signalfeuer des Terminus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 7.\nBenutzen: Ruft ein Legionsschiff herbei, das die Position des Ziels 9 Sek. lang bombardiert und allen Zielen innerhalb von 12 Metern, einschließlich des Schiffs, 30 Feuerschaden zufügt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[151970] = { ["name"] = "Vitalitätsresonator", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 7 Vielseitigkeit\nBenutzen: Lenkt die Lebenskraft eines Gegners um und erhöht Eure Intelligenz 15 Sek. lang um bis zu 18 . Gewährt beim Einsatz gegen Ziele mit hoher Gesundheit mehr Intelligenz. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[151971] = { ["name"] = "Hülle von Asara", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Intelligenz\nAnlegen: Eure Schaden verursachenden Zauber haben eine Chance, 6 Schattenklingen zu beschwören. Nach 2 Sek. beginnen die Klingen, vorwärts zu fliegen. Jede fügt dem ersten getroffenen Gegner in ihrem Weg 16 Schattenschaden zu und erhöht den durch weitere Schattenklingen erlittenen Schaden 3 Sek. lang um 10%, bis zu maximal 50%. (6s Abklingzeit)\nVerkaufspreis:" }
entries[151972] = { ["name"] = "Entweihtes Siegel des Pantheons", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+5 Ausdauer\n+ 7 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 10.\nVerkaufspreis:" }
entries[151973] = { ["name"] = "Halsband der nichtigen Flamme", ["text"] = "Wird beim Aufheben gebunden\nHals\n+4 Ausdauer\n+ 6 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 8.\nVerkaufspreis:" }
entries[151974] = { ["name"] = "Auge von Shatug", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Augen der Hunde (1)\nSchmuck\nAnlegen: Gewährt einem Verbündeten mit Tankspezialisierung in der Nähe, der das entgegengesetzte Auge trägt, zusätzlich 1 Rüstung oder 2 Vielseitigkeit.\nBenutzen: Transformiert in das Auge . (30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[151975] = { ["name"] = "Apokalypseeinheit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 7.\nBenutzen: Verringert den Schaden der nächsten 10 gegen Euch geführten Nahkampfangriffe um bis zu jeweils 38 Schaden. Hält bis zu 20 Sek. lang an.\n\nDas Erleiden von Nahkampfangriffen verringert die Abklingzeit dieser Fähigkeit um 1 Sek. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[151976] = { ["name"] = "Kodex der Risswelt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 7.\nAnlegen: Beim Erleiden von Schaden besteht eine Chance, dass ein Portal zu einer anderen Welt geöffnet wird. Entweder heilt es Euch, gewährt einen Absorptionsschild oder ermächtigt Euch mit Schattenflammenmagie. (4s Abklingzeit)\nVerkaufspreis:" }
entries[151977] = { ["name"] = "Diimas Frostaegis", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Stärke]\nBenutzen: Erhöht Eure Rüstung 12 Sek. lang um 2 , fügt Gegnern innerhalb von 12 Metern 65 Frostschaden zu und verringert 12 Sek. lang ihre Bewegungsgeschwindigkeit um 70%. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[151978] = { ["name"] = "Schwelender Titanenschutz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 7.\nBenutzen: Kanalisiert ein Bollwerk der Flamme, das 3 Sek. lang 512 Schaden absorbiert. Wenn das Bollwerk abläuft, entfesselt Ihr 4 Flammenwellen, die allen Gegnern in ihrem Weg 72 Feuerschaden zufügen.\n\nWährend des Kanalisierens von 'Bollwerk der Flamme' könnt Ihr Euch weder bewegen noch Fähigkeiten einsetzen. (2 Min Abklingzeit)\nVerkaufspreis:" }
