entries[152554] = { ["name"] = "Entweihtes Seetanghemd", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nHemd\nBenötigt den Ruf 'Guter Freund' bei Wichtlus." }
entries[152555] = { ["name"] = "Geisterhai", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren Geisterhai beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt den Ruf 'Guter Freund' bei Ilyssia von den Wassern." }
entries[152556] = { ["name"] = "Fischerboottotem", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört ein Fischerboottotem, das 2 Min. lang die Angelfertigkeit aller Spielercharaktere in der Nähe um 4 erhöht. (5 Min Abklingzeit)\nBenötigt den Ruf 'Guter Freund' bei Akule Flusshorn.\nVerkaufspreis:" }
entries[152557] = { ["name"] = "Stahlhauttrank", ["text"] = "Benutzen: Verleiht Eurem Körper widerstandfähige Energie, die Eure Rüstung 25 Sek. lang um 269 erhöht. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[152558] = { ["name"] = "Stück Kirschkuchen", ["text"] = "Benutzen: Stellt im Verlauf von 30 Sek. ( 910 * 30 / 5) Gesundheit wieder her.\nIhr müsst beim Essen sitzen bleiben.\nVerkaufspreis:" }
entries[152559] = { ["name"] = "Trank des drohenden Todes", ["text"] = "Benutzen: Ermächtigt Euch für 25 Sek. mit Schattenmagie. Sie verleiht Euren Schaden verursachenden Distanzfähigkeiten eine Chance, einen Todesblitz abzufeuern, dessen Schaden sich mit der zurückgelegten Strecke erhöht und der bis zu 331209 Schattenschaden verursacht. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[152560] = { ["name"] = "Trank der Bluteruption", ["text"] = "Benutzen: Erfüllt Euer Blut für 25 Sek. mit Hitze, die Euren Nahkampfangriffen eine Chance gewährt, eine Blutexplosion auszulösen, die 5371 körperlichen Schaden verursacht, der gleichmäßig unter allen Gegnern in der Nähe aufgeteilt wird. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[152561] = { ["name"] = "Trank der Erfrischung", ["text"] = "Benutzen: Versetzt den Trinkenden in einen Zustand höchster Konzentration, in dem er im Verlauf von 10 Sek. bis zu ( 601 * 10) Mana regeneriert, aber wehrlos ist, bis die Konzentration gebrochen wird. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[152564] = { ["name"] = "Festmahl der Fische", ["text"] = "Benutzen: Richtet ein Festmahl der Fische her, das bis zu 50 Mitglieder Eures Schlachtzugs oder Eurer Gruppe sättigen kann!\n\nStellt im Verlauf von 20 Sek. 28846 Gesundheit und 14423 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet alle Eigenschaften eines Fischs.\nVerkaufspreis:" }
entries[152565] = { ["name"] = "Rezept: Festmahl der Fische", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Zubereitung eines Festmahls der Fische.\nBereitet ein Festmahl der Fische zu.\nBenötigt Kochkunst der Verheerten Inseln (1)\nBenötigt den Ruf 'Guter Freund' bei Hüterin Raynae.\nVerkaufspreis:\nFestmahl der Fische\nBenutzen: Richtet ein Festmahl der Fische her, das bis zu 50 Mitglieder Eures Schlachtzugs oder Eurer Gruppe sättigen kann!\n\nStellt im Verlauf von 20 Sek. 28846 Gesundheit und 14423 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet alle Eigenschaften eines Fischs.\nVerkaufspreis:\nBenötigt Verfluchter Königinnenfisch , Mooskiemenbarsch , Hochberglachs , Sturmrochen , Runenschuppenkoi , Schwarzer Barrakuda" }
entries[152566] = { ["name"] = "Mistkäferinnereien", ["text"] = "Questgegenstand\n\"Der glitschige Verdauungstrakt des Mistkäfers verströmt einen abstoßenden Geruch.\"" }
