entries[152599] = { ["name"] = "Himmelsschreckenei", ["text"] = "Questgegenstand\n\"Das schwere Ei fühlt sich warm an.\"" }
entries[152600] = { ["name"] = "Jarkadiax' Auge", ["text"] = "Questgegenstand\n\"Es fühlt sich beinahe so an, als ob das Auge Euch ansieht.\"" }
entries[152601] = { ["name"] = "Geplünderte Vorräte", ["text"] = "Questgegenstand\n\"Verpflegung und Vorräte zum Überleben in der Wüste.\"" }
entries[152602] = { ["name"] = "Überrest von Nhal'athoth", ["text"] = "Questgegenstand\n\"Er ist zwar ausgelaugt, aber ein Kern aus Schatten ist noch vorhanden.\"" }
entries[152610] = { ["name"] = "Sur'jans Greifhaken", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Benutzt Sur'jans Greifhaken, um einen 80 Meter entfernt fliegenden Himmelsschrecken vom Himmel zu holen und ihm regelmäßigen Blutungsschaden zuzufügen. (5 Sek. Abklingzeit)" }
entries[152611] = { ["name"] = "Geronnenes Schreckenszeckenblut", ["text"] = "Questgegenstand\n\"Die Substanz klebt teilweise an Euren Händen, während Ihr sie in eine Flasche füllt.\"" }
entries[152613] = { ["name"] = "Sar'juns Fackel", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Nutzt Sar'juns \"Läuterer\", um besudelte Leichname zu läutern. (5 Sek. Abklingzeit)\n\"Sar'juns 'besondere Fackel' scheint ziemlich normal zu sein, bis auf das getrocknete Blut am unteren Ende.\"" }
entries[152615] = { ["name"] = "Astralheiltrank", ["text"] = "Benutzen: Stellt 13500 Gesundheit wieder her. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[152616] = { ["name"] = "Rezept: Astralheiltrank", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Astralheiltrank herstellt.\nMischt einen Astralheiltrank.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nAstralheiltrank\nBenutzen: Stellt 13500 Gesundheit wieder her. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Astralwinde (20), Kristallphiole" }
entries[152617] = { ["name"] = "Rezept: Astralheiltrank", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Astralheiltrank noch effizienter herstellt.\nMischt Astralheiltränke effektiver.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nAstralheiltrank\nBenutzen: Stellt 13500 Gesundheit wieder her. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Astralwinde (15), Kristallphiole" }
entries[152618] = { ["name"] = "Rezept: Astralheiltrank", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Astralheiltrank noch effizienter herstellt.\nChance auf die Herstellung mehrerer Tränke.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nBenötigt Der Argusvorstoß\n- Ehrfürchtig\nVerkaufspreis:\nAstralheiltrank\nBenutzen: Stellt 13500 Gesundheit wieder her. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Astralwinde (15), Kristallphiole" }
