entries[152626] = { ["name"] = "Insigne der Großen Armee", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Tempowertung um + 5.\nErhöht Eure Meisterschaftswertung um + 5.\n\nPrismatischer Sockel\nAnlegen: Erhöht sämtliche von Euch hervorgerufene Heilung um 2% und sämtlichen von Euch verursachten Schaden um 2%.\nAnlegen: Erhöht die Effekte der vom Netherlichttiegel gewährten Licht- und Schattenkräfte um 50%.\n\"Gemeinsam schreiten wir in den Abgrund.\"\nVerkaufspreis:" }
entries[152627] = { ["name"] = "Lotis Totem", ["text"] = "Questgegenstand\nBenutzen: Beschwört Lotis Totem, das alle Benutzer von Blutmagie innerhalb von 20 Metern aufdeckt. (5 Sek. Abklingzeit)" }
