entries[152725] = { ["name"] = "Technik: Massenmahlung - Astralwinde", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine große Menge Astralwinden mahlt.\nMahlt mehrere Astralwinden gleichzeitig.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nBenötigt Der Argusvorstoß\n- Freundlich\n\nFahle Pigmente\nHandwerksmaterial\n\"Wird häufig beim Mahlen von Pflanzen der Verheerten Inseln gefunden.\"\nVerkaufspreis:\nBenötigt Astralwinde (20)" }
entries[152726] = { ["name"] = "Vorlage: Massensondierung von Empyrium", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man mehrere Chargen Empyrium auf einmal sondiert.\nSondiert mehrere Chargen Empyrium auf einmal.\nBenötigt Juwelierskunst der Verheerten Inseln\n(1)\nBenötigt Armee des Lichts\n- Freundlich\nVerkaufspreis:\nEmpyrium\nHandwerksmaterial\n\"Wird von Spielercharakteren gesammelt, die den Beruf Bergbau ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:\nBenötigt Empyrium (20)" }
entries[152727] = { ["name"] = "Da'juls Feuermojo", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Nutzt einen kleinen Teil von Da'juls Feuermojo, um Zardrax' Skeletthaufen zu zerstören. (5 Sek. Abklingzeit)" }
