entries[152786] = { ["name"] = "Ruf des Verschlingers", ["text"] = "Wird beim Aufheben gebunden\n\"Erschafft ein Knochenbildnis. Knochen von Wichteln, Knochen von Scheusalen, Knochen von Ur'zul. Nur so kann der Vielgesichtige Verschlinger beschwört werden.\"" }
entries[152787] = { ["name"] = "Relikt der Hüter", ["text"] = "Questgegenstand\nEinzigartig (10)\n\"Ein traditionelles Opfer als Zeichen des Respekts für die Statuen der Hüter in Zul'Ahjin.\"" }
entries[152788] = { ["name"] = "Lichtgeschmiedete Kriegspanzerung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört Eure lichtgeschmiedete Kriegspanzerung oder gibt sie wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Armee des Lichts\n- Ehrfürchtig\nVerkaufspreis:\n\"Mit diesen beweglichen Kriegsmaschinen führt die Armee des Lichts schnelle und wirkungsvolle Überfälle durch.\"\nVerkäufer:\nVerteidigerin Jaelaana\nZone:\nArgus\nFraktion:\nArmee des Lichts - Ehrfürchtig\nKosten:" }
entries[152789] = { ["name"] = "Gefesselter Ur'zul", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört Euren gefesselten Ur'zul oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\nVerkaufspreis:\n\"Der Ur'zul ist aus den gequälten Körpern und Seelen gefallener Mitglieder der Armee des Lichts geformt und ist ebenso faszinierend wie entsetzlich.\"\nBeute von:\nArgus, der Zerrütter (Mythisch)" }
entries[152790] = { ["name"] = "Übles Scheusal", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euer übles Scheusal oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\nVerkaufspreis:\n\"Ihr spürt, dass Ihr diese Bestie, die durch ein schreckliches Ritual mit säureartigem Blut erfüllt wurde, kaum zu beherrschen vermögt.\"\nBeute von:\nHundemeister Kerrax\nZone:\nAntorische Ödnis" }
entries[152791] = { ["name"] = "Zügel des zobelschwarzen Ruinpreschers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren zobelschwarzen Ruinprescher oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Der Argusvorstoß\n- Ehrfürchtig\nVerkaufspreis:\n\"Die auf Argus heimischen Talbuks haben im Lauf der Evolution Chitinpanzer entwickelt, um die Jahrzehnte unerbittlichen Kriegs zu überleben, die das Land verwüsten.\"\nVerkäufer:\nToraan der Verehrte\nZone:\nArgus\nFraktion:\nDer Argusvorstoß - Ehrfürchtig\nKosten:" }
