entries[152814] = { ["name"] = "Wahnsinniger Chaosläufer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren wahnsinnigen Chaosläufer oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\n\n\"Die Armee des Lichts konnte nicht alle heimischen Spezies auf Argus retten. Unzählige gingen im Chaos verloren.\"\nBeute von:\nTreiber Kravos\nZone:\nEredath" }
entries[152815] = { ["name"] = "Antorischer Schattenhund", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört Euren antorischen Schattenhund oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Sargeras' Hund war möglicherweise einst ein Teufelspirscher, doch im Laufe der Jahre formte der Dunkle Titan seinen Begleiter neu und ließ ihn deutlich mächtiger werden. Als er schließlich zufrieden war mit seinem Werk, erschuf er noch mehr Hunde und erfüllte sie mit Schatten und Flamme.\"\nErfolg:\nRuhm des Schlachtzüglers von Argus\nKategorie:\nDungeons & Schlachtzüge" }
entries[152816] = { ["name"] = "Antorischer Aschenhund", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört Euren antorischen Aschenhund oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\nVerkaufspreis:\n\"Sargeras' Hund war möglicherweise einst ein Teufelspirscher, doch im Laufe der Jahre formte der Dunkle Titan seinen Begleiter neu und ließ ihn deutlich mächtiger werden. Als er schließlich zufrieden war mit seinem Werk, erschuf er noch mehr Hunde und erfüllte sie mit Schatten und Flamme.\"\nBeute von:\nShatug\nZone:\nAntorus, der Brennende Thron" }
