entries[152901] = { ["name"] = "Beschwörungskristall der Kirin Tor", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man eine violette Zauberschwinge beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört Eure violette Zauberschwinge oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein Geschenk vom Rat der Sechs als Dank für die erneute Rettung Azeroths vor der Legion.\"\nQuest:\nDas Blut eines Titanen\nZone:\nDalaran" }
