entries[152996] = { ["name"] = "Spielzeugboot der Vrykul", ["text"] = "Herbeigezauberter Gegenstand\nEinzigartig (5)\nDauer: 30 min\nBenutzen: Wirft das geflügelte Boot einem freundlichen Spielercharakter zu. Falls er Platz in seinem Rucksack hat, wird er es fangen! (10 Sek. Abklingzeit)" }
entries[152997] = { ["name"] = "Fackel", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Wirft eine Fackel auf nahe Kisten mit nekrotischem Elixier. (5 Sek. Abklingzeit)" }
entries[152998] = { ["name"] = "Sorgfältig versteckter Muffin", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Iss den Muffin! (3 Sek. Abklingzeit)\n\"Womöglich versteckt sich darin ein Preis!\"" }
entries[152999] = { ["name"] = "Wichtelfleisch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert 100 Wichtelfleisch zu einem widerlichen, stinkenden Festmahl. Warum würde das irgendwer essen wollen?" }
entries[153000] = { ["name"] = "Abgegriffene zeitlose Münze", ["text"] = "\"Auf unerklärte Weise noch erkennbar, schmeckt aber scheußlich.\"\nVerkaufspreis:" }
entries[153001] = { ["name"] = "Schwach leuchtende Phönixfeder", ["text"] = "Wird beim Aufheben gebunden\n\"Die Feder verbrennt Euch etwas den Mund.\"\nVerkaufspreis:" }
entries[153002] = { ["name"] = "Kleiner Glücksbringer", ["text"] = "\"Das scheint früher am Halsband eines kleinen Haustiers angebracht gewesen zu sein.\"\nVerkaufspreis:" }
entries[153004] = { ["name"] = "Instabiler Portalemitter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Reißt für 5 Sek. ein Loch in den Wirbelnden Nether, das den... wirklich Mutigen das Reisen gestattet. (30 Min Abklingzeit)\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar.\n\"Vizz durchforstet den Wirbelnden Nether nach zauberhaften und wunderbaren Dingen. Wo das wohl hinführt...\"\nVerkaufspreis:" }
entries[153005] = { ["name"] = "Aufgegebenes Rüstungsset", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Setzt die Machtstufe eines Champions auf 880.\nVerkaufspreis:" }
entries[153006] = { ["name"] = "Grimoire des verlorenen Wissens", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Öffnet Eure Anhängerübersicht und verwendet diesen Gegenstand, um einem Champion 6000 Erfahrung zu verleihen." }
