entries[153010] = { ["name"] = "Blutverklebtes Fellbüschel", ["text"] = "Questgegenstand\n\"Dieses einst weiße Fell ist länger und rauer, als man es bei Tieren hier in der Gegend vorfindet.\"" }
entries[153011] = { ["name"] = "Meiwathas Medaillon", ["text"] = "Questgegenstand\n\"Das kleine goldene Medaillon ist mit einem einzigen Jadestein und dem Namen 'Meiwatha' verziert.\"" }
entries[153012] = { ["name"] = "Fläschchen mit vergiftetem Mojo", ["text"] = "Questgegenstand\nBenutzen: Füttert eine gezähmte Kriegsbrut mit einer Dosis vergifteten Mojos. (2 Sek. Abklingzeit)" }
entries[153013] = { ["name"] = "Widerliches Festmahl", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Richtet ein widerliches Festmahl für... die Verrückten aus, die so etwas essen würden." }
entries[153014] = { ["name"] = "Makelloser Argunit", ["text"] = "Questgegenstand" }
entries[153015] = { ["name"] = "Schachtel voller leerenverseuchter Wesen", ["text"] = "Einzigartig (20)\nBenutzen: Wirft die Kiste und schleudert ihren Inhalt heraus. (5 Sek. Abklingzeit)\n\"Ihr seid ob des Inhalts genauso neugierig wie entsetzt.\"\nVerkaufspreis:" }
entries[153016] = { ["name"] = "Versiegelte Schriftrolle", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein aufwendiges Emblem wurde mit einem Stempel in das Wachsiegel gedrückt.\"" }
entries[153017] = { ["name"] = "Grober Spaltzungenbalg", ["text"] = "Questgegenstand\n\"Sehr rau und trocken.\"" }
entries[153018] = { ["name"] = "Verderbter Mantel der Teufelssucher", ["text"] = "Wird beim Anlegen gebunden\nSchulter Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\n+ 3 Vielseitigkeit\nHaltbarkeit 100 / 100\nVerkaufspreis:" }
entries[153019] = { ["name"] = "Beinplatten des kolossalen Vernichters", ["text"] = "Wird beim Anlegen gebunden\nBeine Platte\n16 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\n+ 6 Vielseitigkeit\nHaltbarkeit 120 / 120\nVerkaufspreis:" }
entries[153020] = { ["name"] = "Makellose Eisbrocken", ["text"] = "Questgegenstand\n\"Mit Magie erfüllte glasähnliche Eisbrocken. Bleiben eine unnatürlich lange Zeit lang gefroren.\"" }
entries[153021] = { ["name"] = "Intaktes Dämonenauge", ["text"] = "Wird beim Aufheben gebunden\n\"Aus dem Schädel eines der furchterregendsten Dämonen der Legion in der Antorischen Ödnis gerissen.\"" }
entries[153022] = { ["name"] = "Tortollanische Schriftrolle", ["text"] = "Questgegenstand\n\"Sie scheint vor magischem Potenzial zu pulsieren.\"" }
entries[153023] = { ["name"] = "Lichtgeschmiedete Verstärkungsrune", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erhöht die Beweglichkeit, Intelligenz und Stärke für 1 Stunde um 11 . Verstärkungsrune. (1 Min Abklingzeit)\nBenötigt Armee des Lichts\n- Ehrfürchtig\nVerkaufspreis:" }
entries[153024] = { ["name"] = "Schriftrolle der Verbrennung", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Liest eine magische Schriftrolle, um Schreckenszecken in der Nähe zu zerstören. (5 Sek. Abklingzeit)" }
entries[153025] = { ["name"] = "Schriftrolle der Reinigung", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Liest eine magische Schriftrolle, um ein Blutritual in der Nähe zu unterbrechen." }
entries[153026] = { ["name"] = "Schielauge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar." }
entries[153027] = { ["name"] = "Verwaistes Marsuul", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Der Argusvorstoß\n- Wohlwollend" }
entries[153028] = { ["name"] = "Heilige Überreste", ["text"] = "Questgegenstand\n\"Die uralte Macht der Donnerechsen fließt immer noch durch diese Knochen.\"" }
entries[153029] = { ["name"] = "Rorgogs Antennen", ["text"] = "Questgegenstand\n\"Diese ungewöhnlich großen Antennen können donnernden Kräften widerstehen.\"" }
